Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
wifi: ath12k: change DMA direction while mapping reinjected
 packets
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

For fragmented packets, ath12k reassembles each fragment as a normal
packet and then reinjects it into HW ring. In this case, the DMA
direction should be DMA_TO_DEVICE, not DMA_FROM_DEVICE. Otherwise,
an invalid payload may be reinjected into the HW and
subsequently delivered to the host.

Given that arbitrary memory can be allocated to the skb buffer,
knowledge about the data contained in the reinjected buffer is lacking.
Consequently, there’s a risk of private information being leaked.

Tested-on: QCN9274 hw2.0 PCI WLAN.WBE.1.1.1-00209-QCAHKSWPL_SILICONZ-1

Fixes: d889913205cf ("wifi: ath12k: driver for Qualcomm Wi-Fi 7 devices")
Co-developed-by: Baochen Qiang <quic_bqiang@quicinc.com>
Signed-off-by: Baochen Qiang <quic_bqiang@quicinc.com>
Signed-off-by: P Praneesh <quic_ppranees@quicinc.com>
Acked-by: Jeff Johnson <quic_jjohnson@quicinc.com>
Signed-off-by: Kalle Valo <quic_kvalo@quicinc.com>
Link: https://msgid.link/20240520070045.631029-2-quic_ppranees@quicinc.com

Here is the root cause:
The bug was caused by incorrectly using the DMA direction `DMA_FROM_DEVICE` when reinjecting fragmented packets into the hardware ring. This led to the potential for invalid payloads being sent to the hardware, which could result in the delivery of arbitrary and potentially sensitive data to the host, as the driver lacked knowledge about the contents of the reinjected buffer.

Here is the patch:

 static int ath12k_dp_rx_h_defrag_reo_reinject(struct ath12k *ar,
 					      struct ath12k_dp_rx_tid *rx_tid,
 					      struct sk_buff *defrag_skb)
 {
 	struct ath12k_base *ab = ar->ab;
 	struct ath12k_dp *dp = &ab->dp;
 	struct hal_rx_desc *rx_desc = (struct hal_rx_desc *)defrag_skb->data;
 	struct hal_reo_entrance_ring *reo_ent_ring;
 	struct hal_reo_dest_ring *reo_dest_ring;
 	struct dp_link_desc_bank *link_desc_banks;
 	struct hal_rx_msdu_link *msdu_link;
 	struct hal_rx_msdu_details *msdu0;
 	struct hal_srng *srng;
 	dma_addr_t link_paddr, buf_paddr;
 	u32 desc_bank, msdu_info, msdu_ext_info, mpdu_info;
 	u32 cookie, hal_rx_desc_sz, dest_ring_info0;
 	int ret;
 	struct ath12k_rx_desc_info *desc_info;
 	enum hal_rx_buf_return_buf_manager idle_link_rbm = dp->idle_link_rbm;
 	u8 dst_ind;

 	hal_rx_desc_sz = ab->hal.hal_desc_sz;
 	link_desc_banks = dp->link_desc_banks;
 	reo_dest_ring = rx_tid->dst_ring_desc;

 	ath12k_hal_rx_reo_ent_paddr_get(ab, &reo_dest_ring->buf_addr_info,
 					&link_paddr, &cookie);
 	desc_bank = u32_get_bits(cookie, DP_LINK_DESC_BANK_MASK);

 	msdu_link = (struct hal_rx_msdu_link *)(link_desc_banks[desc_bank].vaddr +
 			(link_paddr - link_desc_banks[desc_bank].paddr));
 	msdu0 = &msdu_link->msdu_link[0];
 	msdu_ext_info = le32_to_cpu(msdu0->rx_msdu_ext_info.info0);
 	dst_ind = u32_get_bits(msdu_ext_info, RX_MSDU_EXT_DESC_INFO0_REO_DEST_IND);

 	memset(msdu0, 0, sizeof(*msdu0));

 	msdu_info = u32_encode_bits(1, RX_MSDU_DESC_INFO0_FIRST_MSDU_IN_MPDU) |
 		    u32_encode_bits(1, RX_MSDU_DESC_INFO0_LAST_MSDU_IN_MPDU) |
 		    u32_encode_bits(0, RX_MSDU_DESC_INFO0_MSDU_CONTINUATION) |
 		    u32_encode_bits(defrag_skb->len - hal_rx_desc_sz,
 				    RX_MSDU_DESC_INFO0_MSDU_LENGTH) |
 		    u32_encode_bits(1, RX_MSDU_DESC_INFO0_VALID_SA) |
 		    u32_encode_bits(1, RX_MSDU_DESC_INFO0_VALID_DA);
 	msdu0->rx_msdu_info.info0 = cpu_to_le32(msdu_info);
 	msdu0->rx_msdu_ext_info.info0 = cpu_to_le32(msdu_ext_info);

 	/* change msdu len in hal rx desc */
 	ath12k_dp_rxdesc_set_msdu_len(ab, rx_desc, defrag_skb->len - hal_rx_desc_sz);

 	buf_paddr = dma_map_single(ab->dev, defrag_skb->data,
 				   defrag_skb->len + skb_tailroom(defrag_skb),
-				   DMA_FROM_DEVICE);
+				   DMA_TO_DEVICE);
 	if (dma_mapping_error(ab->dev, buf_paddr))
 		return -ENOMEM;

 	spin_lock_bh(&dp->rx_desc_lock);
 	desc_info = list_first_entry_or_null(&dp->rx_desc_free_list,
 					     struct ath12k_rx_desc_info,
 					     list);
 	if (!desc_info) {
 		spin_unlock_bh(&dp->rx_desc_lock);
 		ath12k_warn(ab, "failed to find rx desc for reinject\n");
 		ret = -ENOMEM;
 		goto err_unmap_dma;
 	}

 	desc_info->skb = defrag_skb;
 	desc_info->in_use = true;

 	list_del(&desc_info->list);
 	spin_unlock_bh(&dp->rx_desc_lock);

 	ATH12K_SKB_RXCB(defrag_skb)->paddr = buf_paddr;

 	ath12k_hal_rx_buf_addr_info_set(&msdu0->buf_addr_info, buf_paddr,
 					desc_info->cookie,
 					HAL_RX_BUF_RBM_SW3_BM);

 	/* Fill mpdu details into reo entrance ring */
 	srng = &ab->hal.srng_list[dp->reo_reinject_ring.ring_id];

 	spin_lock_bh(&srng->lock);
 	ath12k_hal_srng_access_begin(ab, srng);

 	reo_ent_ring = ath12k_hal_srng_src_get_next_entry(ab, srng);
 	if (!reo_ent_ring) {
 		ath12k_hal_srng_access_end(ab, srng);
 		spin_unlock_bh(&srng->lock);
 		ret = -ENOSPC;
 		goto err_free_desc;
 	}
 	memset(reo_ent_ring, 0, sizeof(*reo_ent_ring));

 	ath12k_hal_rx_buf_addr_info_set(&reo_ent_ring->buf_addr_info, link_paddr,
 					cookie,
 					idle_link_rbm);

 	mpdu_info = u32_encode_bits(1, RX_MPDU_DESC_INFO0_MSDU_COUNT) |
 		    u32_encode_bits(0, RX_MPDU_DESC_INFO0_FRAG_FLAG) |
 		    u32_encode_bits(1, RX_MPDU_DESC_INFO0_RAW_MPDU) |
 		    u32_encode_bits(1, RX_MPDU_DESC_INFO0_VALID_PN) |
 		    u32_encode_bits(rx_tid->tid, RX_MPDU_DESC_INFO0_TID);

 	reo_ent_ring->rx_mpdu_info.info0 = cpu_to_le32(mpdu_info);
 	reo_ent_ring->rx_mpdu_info.peer_meta_data =
 		reo_dest_ring->rx_mpdu_info.peer_meta_data;

 	/* Firmware expects physical address to be filled in queue_addr_lo in
 	 * the MLO scenario and in case of non MLO peer meta data needs to be
 	 * filled.
 	 * TODO: Need to handle for MLO scenario.
 	 */
 	reo_ent_ring->queue_addr_lo = reo_dest_ring->rx_mpdu_info.peer_meta_data;
 	reo_ent_ring->info0 = le32_encode_bits(dst_ind,
 					       HAL_REO_ENTR_RING_INFO0_DEST_IND);

 	reo_ent_ring->info1 = le32_encode_bits(rx_tid->cur_sn,
 					       HAL_REO_ENTR_RING_INFO1_MPDU_SEQ_NUM);
 	dest_ring_info0 = le32_get_bits(reo_dest_ring->info0,
 					HAL_REO_DEST_RING_INFO0_SRC_LINK_ID);
 	reo_ent_ring->info2 =
 		cpu_to_le32(u32_get_bits(dest_ring_info0,
 					 HAL_REO_ENTR_RING_INFO2_SRC_LINK_ID));

 	ath12k_hal_srng_access_end(ab, srng);
 	spin_unlock_bh(&srng->lock);

 	return 0;

 err_free_desc:
 	spin_lock_bh(&dp->rx_desc_lock);
 	desc_info->in_use = false;
 	desc_info->skb = NULL;
 	list_add_tail(&desc_info->list, &dp->rx_desc_free_list);
 	spin_unlock_bh(&dp->rx_desc_lock);
 err_unmap_dma:
 	dma_unmap_single(ab->dev, buf_paddr, defrag_skb->len + skb_tailroom(defrag_skb),
-			 DMA_FROM_DEVICE);
+			 DMA_TO_DEVICE);
 	return ret;
 }



